UnityEditor.EditorApplication.delayCall+=()=>{try{
UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");var race=UnityEngine.Object.FindAnyObjectByType<Racer.RaceDirector>();var branches=UnityEngine.Object.FindObjectsByType<Racer.WoodlandRoute>();var rows=System.IO.File.ReadAllLines("Docs/ReverseShortcuts/third-candidate-driving.csv").Skip(1).Select(s=>s.Split(',')).ToArray();var results=new List<string>();foreach(var profile in new[]{"moto","atv"})foreach(var branch in branches){var samples=rows.Where(r=>r[0]==profile+"-"+branch.title).Select(r=>new Vector3(float.Parse(r[3],System.Globalization.CultureInfo.InvariantCulture),float.Parse(r[4],System.Globalization.CultureInfo.InvariantCulture),float.Parse(r[5],System.Globalization.CultureInfo.InvariantCulture))).ToArray();bool entered=false;for(int i=1;i<samples.Length;i++)entered|=branch.Enter(samples[i-1],samples[i],samples[i]-samples[i-1]);results.Add((entered?"PASS ":"FAIL ")+profile+" recorded physical entry: "+branch.title);}
